import java.util.*;
class Counter {private int value;synchronized void increment(){value++;}synchronized int get(){return value;}}
public class Main {public static void main(String[] args)throws Exception{Scanner s=new Scanner(System.in);int n=s.nextInt(),m=s.nextInt();Counter c=new Counter();List<Thread> ts=new ArrayList<>();for(int i=0;i<n;i++)ts.add(new Thread(()->{for(int j=0;j<m;j++)c.increment();}));ts.forEach(Thread::start);for(Thread t:ts)t.join();System.out.println(c.get());}}

